<template>
    <div class="flex flex-row flex-wrap align-v-center pv-2">
        <div class="flex flex-column pv-2">
            <div
                class="flex flex-row nmh-1 flex-wrap"
            >
                <div class="flex flex-column resource-button ph-1">
                    <button
                        class="btn stacked"
                        @click="likeContent"
                    >
                        <span
                            class="tw-shadow-none"
                            style="padding:0 8px; border: none; box-shadow: none;"
                            :class="hasLiked ? themeTextClass : 'text-grey-3 dark:tw-text-white'"
                        >
                            <i
                                class="fa-thumbs-up mb-1"
                                :class="hasLiked ? 'fas' : 'fal'"
                            ></i>
                            {{ totalLikes }}
                        </span>
                    </button>
                </div>

                <div class="flex flex-column resource-button ph-1">
                    <button
                        class="btn stacked"
                        data-open-modal="shareVideoModal"
                    >
                        <span
                            class="text-grey-3 dark:tw-text-white tw-shadow-none"
                            style="padding:0 8px; box-shadow: none;"
                        >
                            <i class="fas fa-share mb-1"></i>
                            Share
                        </span>
                    </button>
                </div>

                <div
                    v-if="resources.length > 0"
                    class="flex flex-column resource-button ph-1 relative"
                >
                    <button
                        class="btn open-resources stacked"
                        @click="resourceDropdown = !resourceDropdown"
                    >
                        <span
                            class="tw-shadow-none"
                            :class="resourceDropdown ? themeTextClass : 'text-grey-3 dark:tw-text-white'"
                            style="padding:0 8px; box-shadow: none;"
                        >
                            <i class="fas fa-download mb-1"></i>
                            Downloads
                        </span>
                    </button>

                    <transition name="grow-fade">
                        <div
                            v-show="resourceDropdown"
                            class="download-dropdown tw-absolute"
                        >
                            <div class="tw-flex tw-flex-wrap tw-bg-white tw-rounded-lg tw-shadow-lg tw-overflow-hidden">
                                <a
                                    v-for="resource in resources"
                                    :key="resource.resource_name"
                                    :href="resource.resource_url"
                                    :aria-label="`Download ${resource.resource_name}`"
                                    class="flex flex-row pa-1 tiny no-decoration text-black
                                           hover-bg-grey-1 align-v-center nowrap"
                                    target="_blank"
                                    download
                                >
                                    <i
                                        class="fas mr-1"
                                        style="font-size:16px;"
                                        :class="getResourceIcon(resource.resource_url)"
                                    ></i>
                                    {{ resource.resource_name }}
                                </a>
                            </div>
                        </div>
                    </transition>
                </div>

                <div class="flex flex-column resource-button ph-1">
                    <button
                        class="btn stacked"
                        @click="addToList"
                    >
                        <span
                            class="tw-shadow-none"
                            style="padding:0 8px; box-shadow: none;"
                            :class="hasAdded ? themeTextClass : 'text-grey-3 dark:tw-text-white'"
                        >
                            <i
                                class="fas mb-1"
                                :class="hasAdded ? 'fa-times' : 'fa-plus'"
                            ></i>
                            <span class="hide-xs-only">
                                {{ hasAdded ? 'Added' : 'Add to List' }}
                            </span>
                            <span class="hide-sm-up">
                                {{ hasAdded ? 'Added' : 'Add' }}
                            </span>
                        </span>
                    </button>
                </div>
            </div>
        </div>


        <div
            id="shareVideoModal"
            class="modal"
        >
            <div class="flex flex-column bg-white corners-10 shadow pa-3">
                <h1 class="heading mb-2">
                    Share Video Link
                </h1>


                <div class="form-group mb-2">
                    <input
                        id="shareableUrlInput"
                        class="no-label mb-2"
                        type="text"
                        :value="shareUrl"
                    >

                    <button
                        id="copyUrlButton"
                        class="btn"
                        @click="copyTimecodeToClipboard"
                    >
                        <span class="text-white bg-grey-3 tw-shadow-none">
                            Copy
                        </span>
                    </button>
                </div>

                <p class="tiny font-italic text-grey-3 dark:tw-text-white">
                    This link is only accessible by {{ toCapitalCase(brand) }} Members.
                </p>
            </div>
        </div>
    </div>
</template>

<script>
import Utils from '../../assets/js/helper-functions/utils.js';
import ThemeClasses from '../../mixins/ThemeClasses';
import Toasts from '../../assets/js/classes/toasts';
import ContentService from '../../assets/js/services/content';

export default {
    name: 'ContentLessonActionButtons',
    mixins: [ThemeClasses],
    props: {
        brand: {
            type: String,
            default: () => 'drumeo',
        },

        title: {
            type: String,
            default: () => '',
        },

        parentTitle: {
            type: String,
            default: () => null,
        },

        instructors: {
            type: Array,
            default: () => [],
        },

        isLiked: {
            type: Boolean,
            default: () => false,
        },

        isAdded: {
            type: Boolean,
            default: () => false,
        },

        likeCount: {
            type: Number,
            default: () => 0,
        },

        userId: {
            type: [String, Number],
            default: () => null,
        },

        contentId: {
            type: [String, Number],
            default: () => null,
        },

        resources: {
            type: Array,
            default: () => [],
        },
    },

    data() {
        return {
            resourceDropdown: false,
            hasLiked: this.isLiked,
            totalLikes: this.likeCount,
            hasAdded: this.isAdded,
            useTimecode: true,
        };
    },

    computed: {
        subtitle() {
            if (this.parentTitle) {
                return `From ${this.parentTitle}`;
            }

            return `With ${this.instructors.join(', ')}`;
        },

        currentTime() {
            const { mediaElementVueInstance } = this.$root.$refs;

            if (mediaElementVueInstance) {
                return mediaElementVueInstance.currentTimeInSeconds;
            }

            return 0;
        },

        shareUrl() {
            return `${location.protocol}//${location.host}${location.pathname}`;
        },
    },
    mounted() {
        document.addEventListener('click', (event) => {
            if (!event.target.matches('.open-resources')) {
                this.resourceDropdown = false;
            }
        });
    },
    methods: {
        likeContent() {
            this.hasLiked = !this.hasLiked;

            if (this.hasLiked) {
                this.totalLikes += 1;
            } else {
                this.totalLikes -= 1;
            }

            ContentService.likeContentById({
                is_liked: this.hasLiked,
                content_id: this.contentId,
                user_id: this.userId,
            });
        },

        toCapitalCase: string => Utils.toCapitalCase(string),

        addToList() {
            this.hasAdded = !this.hasAdded;

            this.$nextTick(() => { ContentService.addOrRemoveContentFromList(this.contentId, !this.hasAdded); });
        },

        getResourceIcon(resource) {
            const urlParts = resource.split('.');
            const fileExtension = urlParts[urlParts.length - 1];
            const iconMap = {
                pdf: 'fa-file-pdf',
                mp3: 'fa-file-music',
                zip: 'fa-file-archive',
            };

            return iconMap[fileExtension] || 'fa-file-download';
        },

        copyTimecodeToClipboard() {
            const timecode = document.getElementById('shareableUrlInput');

            if (navigator.userAgent.match(/ipad|ipod|iphone/i)) {
                const editable = timecode.contentEditable;
                const { readOnly } = timecode;
                const range = document.createRange();
                const selection = window.getSelection();

                timecode.contentEditable = true;
                timecode.readOnly = false;
                range.selectNodeContents(timecode);
                selection.removeAllRanges();
                selection.addRange(range);
                timecode.setSelectionRange(0, 999999);
                timecode.contentEditable = editable;
                timecode.readOnly = readOnly;
            } else {
                timecode.select();
            }
            document.execCommand('copy');
            timecode.blur();
            window.closeAllModals();

            Toasts.push({
                icon: 'happy',
                title: 'SHARE THE LOVE!',
                message: 'This URL has been copied, and is ready to share!',
            });
        },
    },
};
</script>
