___CSS_LOADER_EXPORT___.push([module.id, ".loop-play-button{flex:0 0 33.3333%;max-width:33.3333%;min-width:33.3333%}@media screen and (min-width:40rem){.loop-play-button{flex:0 0 100px;max-width:100px;min-width:100px}}", "",{"version":3,"sources":["webpack://./resources/platform/assets/js/vue/vuesora/components/LegacyLoops/LegacyLoops.vue","webpack://./resources/platform/assets/js/vue/vuesora/assets/sass/partials/_variables.scss"],"names":[],"mappings":"AAGI,kBACI,iBAAA,CACA,kBAAA,CACA,kBAUR,CCeE,oCD5BE,kBAMQ,cAAA,CACA,eAAA,CACA,eAWV,CACF","sourcesContent":["\n    @import '../../assets/sass/partials/_variables.scss';\n\n    .loop-play-button {\n        flex:0 0 33.3333%;\n        max-width:33.3333%;\n        min-width:33.3333%;\n\n        @include small {\n            flex:0 0 100px;\n            max-width:100px;\n            min-width:100px;\n        }\n    }\n","///////////////////////////////////////\n///\n/// TABLE OF CONTENTS\n///\n/// 1. GRID\n/// 2. FONTS\n/// 3. COLORS\n/// 4. POSITIONING\n///\n///////////////////////////////////////\n\n///////////////////////////////////////\n/// 1. GRID\n///////////////////////////////////////\n\n// Fixed Container\n$fixedRowWidth: 62.5rem;  // 1000px\n\n// Gutters\n$gutterWidth: 1.875rem;   // 30px - usually divided by 2 or 3\n\n// Breakpoints\n$small: 40rem;             // 640px\n$medium: 64rem;            // 1024px\n$large: 72.5rem;           // 1240px\n$xLarge: 97.5rem;           // 1560px\n\n// Breakpoint Mixins\n// Breakpoints start mobile first. xSmall is technically the default breakpoint, so it doesn't need to be defined\n\n@mixin small {\n  @media screen and (min-width: #{$small}) {\n    @content;\n  }\n}\n\n@mixin medium {\n  @media screen and (min-width: #{$medium}) {\n    @content;\n  }\n}\n\n@mixin large {\n  @media screen and (min-width: #{$large}) {\n    @content;\n  }\n}\n\n@mixin xLarge {\n  @media screen and (min-width: #{$xLarge}) {\n    @content;\n  }\n}\n\n@mixin highDpi {\n  @media only screen and (-webkit-min-device-pixel-ratio: 1.3),\n  only screen and (-o-min-device-pixel-ratio: 13/10),\n  only screen and (min-resolution: 120dpi) {\n    @content;\n  }\n}\n\n@mixin xSmallOnly {\n  @media screen and (max-width: #{$small - .0625rem}) {\n    @content;\n  }\n}\n\n@mixin smallOnly {\n  @media screen and (min-width: #{$small}) and (max-width: #{$medium - .0625rem}) {\n    @content;\n  }\n}\n\n@mixin mediumOnly {\n  @media screen and (min-width: #{$medium}) and (max-width: #{$large - .0625rem}) {\n    @content;\n  }\n}\n\n@mixin largeOnly {\n  @media screen and (min-width: #{$large}) and (max-width: #{$xLarge - .0625rem}) {\n    @content;\n  }\n}\n\n\n///////////////////////////////////////\n/// 2. FONTS\n///////////////////////////////////////\n\n$defaultSansSerif: 'Open Sans', sans-serif;\n$secondarySansSerif: 'Bebas Neue', sans-serif;\n\n$defaultSerif: 'Bree Serif', serif;\n$secondarySerif: 'Times New Roman', serif;\n\n$defaultMonospace: 'Courier New', monospace;\n\n///////////////////////////////////////\n/// 3. COLORS\n///////////////////////////////////////\n\n$backgroundGray: #fff;\n$darkGray:#a8a8a8;\n$lightGray:#d1d1d1;\n$greys: (\n  1: #e5e8e8,\n  2: #ccd3d3,\n  3: #8c9698,\n  4: #565d5f,\n  5: #191b1c,\n  6: #1a222b,\n  7: #f3f9ff\n);\n\n// Vuesora Colors\n$primary:#362063;\n$secondary:#42b983;\n\n// Brand Colors\n$drumeoBlue:#0B76DB;\n$guitareoGreen:#00C9AC;\n$guitareoGuitarQuestYellow:#FFB500;\n$guitareoGuitarQuestGray:#313131;\n$pianoteRed:#F61A30;\n$pianoteGreen:#232e31;\n$recordeoYellow:#FFAE00;\n$singeoPurple:#8300E9;\n\n$brand_colors: (\n  drumeo: $drumeoBlue,\n  guitareo: $guitareoGreen,\n  guitareoGuitarQuest: $guitareoGuitarQuestYellow,\n  pianote: $pianoteRed,\n  singeo: $singeoPurple,\n  recordeo: $recordeoYellow\n);\n\n// General Colors\n$successGreen:#4bb543;\n$warningYellow:#FFCC00;\n$errorRed:#F71B26;\n$liveRed:#F71B26;\n\n// Content Colors\n$content_colors: (\n  course: #07A0FF,\n  pack: #07A0FF,\n  song: #F8004F,\n  play-along: #FFB500,\n  student-focus: #A82FFF,\n  rudiment: #d06835,\n  dft: #0DD3BF,\n  learning-path: #0B76DB,\n  my-list: $drumeoBlue,\n  show: #00C278,\n  semester-pack: #00BC75,\n);\n\n$sidebarLink:#4D5356;\n\n$coachYellow:#FAA300;\n$lifetimeBlue:#07B3FF;\n\n/**\n* Make a horizontal gradient with 2 colors\n*\n* @param $primaryColor - the first color at the start of the gradient\n* @param $secondaryColor - the second color at the end of the gradient\n*/\n@mixin leftToRightGradient($primaryColor, $secondaryColor){\n  background: -moz-linear-gradient(left, $primaryColor 0%, $secondaryColor 100%);\n  background: -webkit-linear-gradient(left, $primaryColor 0%,$secondaryColor 100%);\n  background: linear-gradient(to right, $primaryColor 0%,$secondaryColor 100%);\n}\n\n/**\n* Make a vertical gradient with 2 colors\n*\n* @param $primaryColor - the first color at the start of the gradient\n* @param $secondaryColor - the second color at the end of the gradient\n*/\n@mixin topToBottomGradient($primaryColor, $secondaryColor){\n  background: -moz-linear-gradient(top, $primaryColor 0%, $secondaryColor 100%);\n  background: -webkit-linear-gradient(top, $primaryColor 0%,$secondaryColor 100%);\n  background: linear-gradient(to bottom, $primaryColor 0%,$secondaryColor 100%);\n}\n\n///////////////////////////////////////\n/// 4. POSITIONING\n///////////////////////////////////////\n\n@mixin flexCenter {\n  display:flex;\n  flex-direction:column;\n  justify-content:center;\n  align-items:center;\n}\n\n@mixin centerVertical {\n  position:absolute;\n  top:50%;\n  transform:translateY(-50%);\n  -webkit-transform:translateY(-50%);\n  -moz-transform:translateY(-50%);\n}\n\n@mixin centerHorizontal {\n  position:absolute;\n  left:50%;\n  transform:translateX(-50%);\n  -webkit-transform:translateX(-50%);\n  -moz-transform:translateX(-50%);\n}\n\n@mixin centerBoth {\n  position:absolute;\n  top:50%;\n  left:50%;\n  transform:translate(-50%, -50%);\n  -webkit-transform:translate(-50%,-50%);\n  -moz-transform:translate(-50%,-50%);\n}"],"sourceRoot":""}]);
