___CSS_LOADER_EXPORT___.push([module.id, ".flex.arrow-column{display:flex;flex:0 0 60px;padding-right:10px}.complete-column{margin-top:.9375rem}@media screen and (min-width:64rem){.complete-column{margin-top:0}}@media screen and (min-width:40rem){.assignment-title{flex:0 0 auto}}#practiceOverlay{bottom:0;left:0;position:fixed;right:0;top:58px;z-index:100}#practiceOverlay .loading-exercise{left:50%;position:absolute;top:50%;transform:translate(-50%,-50%)}#ssEmbed,.embed-column{height:100%}#ssEmbed{left:0;position:absolute;top:0;width:100%}.carousel{position:relative}.carousel .page{transform:translateX(0);transition:transform .4s ease-in-out;will-change:transform}.carousel .page img{width:100%}.carousel .side-button{background-color:transparent;cursor:pointer;height:100%;position:absolute;top:0;transition:background-color .2s ease-in-out;width:1.875rem;will-change:background-color}.carousel .side-button i{font-size:20px}.carousel .side-button:hover{background-color:#f2f2f2}.carousel .side-button.prev{left:0}.carousel .side-button.next{right:0}.carousel .page-buttons{bottom:0;left:50%;position:absolute;transform:translateX(-50%);white-space:nowrap}.carousel .page-buttons .page-button{border-width:2px;cursor:pointer;display:inline-block;height:12px;width:12px}", "",{"version":3,"sources":["webpack://./resources/platform/assets/js/vue/vuesora/components/ContentAssignment/ContentAssignment.vue","webpack://./resources/platform/assets/js/vue/vuesora/assets/sass/partials/_variables.scss"],"names":[],"mappings":"AAEA,mBACI,YAAA,CACA,aAAA,CACA,kBAWJ,CARA,iBACI,mBAWJ,CCiBE,oCD7BF,iBAGQ,YAaN,CACF,CCME,oCDhBF,kBAEQ,aAaN,CACF,CAVA,iBAKI,QAAA,CAFA,MAAA,CAFA,cAAA,CAGA,OAAA,CAFA,QAAA,CAIA,WAaJ,CAXI,mCAGI,QAAA,CAFA,iBAAA,CACA,OAAA,CAEA,8BAaR,CALA,uBAHI,WAoBJ,CAjBA,SAKI,MAAA,CAFA,iBAAA,CACA,KAAA,CAHA,UAgBJ,CATA,UACI,iBAYJ,CAXI,gBACI,uBAAA,CAEA,oCAAA,CADA,qBAcR,CAZQ,oBACI,UAcZ,CAXI,uBAII,4BAAA,CAGA,cAAA,CAJA,WAAA,CAFA,iBAAA,CACA,KAAA,CAIA,2CAAA,CAEA,cChDM,CD6CN,4BAgBR,CAZQ,yBACI,cAcZ,CAZQ,6BACI,wBAcZ,CAZQ,4BACI,MAcZ,CAZQ,4BACI,OAcZ,CAXI,wBAEI,QAAA,CACA,QAAA,CAFA,iBAAA,CAGA,0BAAA,CACA,kBAaR,CAZQ,qCAII,gBAAA,CACA,cAAA,CAFA,oBAAA,CAFA,WAAA,CACA,UAiBZ","sourcesContent":["\n@import '../../assets/sass/partials/variables';\n.flex.arrow-column {\n    display: flex;\n    flex: 0 0 60px;\n    padding-right: 10px;\n}\n\n.complete-column {\n    margin-top: $gutterWidth / 2;\n    @include medium {\n        margin-top: 0;\n    }\n}\n\n.assignment-title {\n    @include small {\n        flex: 0 0 auto;\n    }\n}\n\n#practiceOverlay {\n    position: fixed;\n    top: 58px;\n    left: 0;\n    right: 0;\n    bottom: 0;\n    z-index: 100;\n\n    .loading-exercise {\n        position: absolute;\n        top: 50%;\n        left: 50%;\n        transform: translate(-50%, -50%);\n    }\n}\n\n.embed-column {\n    height: 100%;\n}\n\n#ssEmbed {\n    width: 100%;\n    height: 100%;\n    position: absolute;\n    top: 0;\n    left: 0;\n}\n\n.carousel {\n    position: relative;\n    .page {\n        transform: translateX(0);\n        will-change: transform;\n        transition: transform .4s ease-in-out;\n        img {\n            width: 100%;\n        }\n    }\n    .side-button {\n        position: absolute;\n        top: 0;\n        height: 100%;\n        background-color: transparent;\n        will-change: background-color;\n        transition: background-color .2s ease-in-out;\n        cursor: pointer;\n        width: $gutterWidth;\n        i {\n            font-size: 20px;\n        }\n        &:hover {\n            background-color: #f2f2f2;\n        }\n        &.prev {\n            left: 0;\n        }\n        &.next {\n            right: 0;\n        }\n    }\n    .page-buttons {\n        position: absolute;\n        bottom: 0;\n        left: 50%;\n        transform: translateX(-50%);\n        white-space: nowrap;\n        .page-button {\n            height: 12px;\n            width: 12px;\n            display: inline-block;\n            border-width: 2px;\n            cursor: pointer;\n        }\n    }\n}\n","///////////////////////////////////////\n///\n/// TABLE OF CONTENTS\n///\n/// 1. GRID\n/// 2. FONTS\n/// 3. COLORS\n/// 4. POSITIONING\n///\n///////////////////////////////////////\n\n///////////////////////////////////////\n/// 1. GRID\n///////////////////////////////////////\n\n// Fixed Container\n$fixedRowWidth: 62.5rem;  // 1000px\n\n// Gutters\n$gutterWidth: 1.875rem;   // 30px - usually divided by 2 or 3\n\n// Breakpoints\n$small: 40rem;             // 640px\n$medium: 64rem;            // 1024px\n$large: 72.5rem;           // 1240px\n$xLarge: 97.5rem;           // 1560px\n\n// Breakpoint Mixins\n// Breakpoints start mobile first. xSmall is technically the default breakpoint, so it doesn't need to be defined\n\n@mixin small {\n  @media screen and (min-width: #{$small}) {\n    @content;\n  }\n}\n\n@mixin medium {\n  @media screen and (min-width: #{$medium}) {\n    @content;\n  }\n}\n\n@mixin large {\n  @media screen and (min-width: #{$large}) {\n    @content;\n  }\n}\n\n@mixin xLarge {\n  @media screen and (min-width: #{$xLarge}) {\n    @content;\n  }\n}\n\n@mixin highDpi {\n  @media only screen and (-webkit-min-device-pixel-ratio: 1.3),\n  only screen and (-o-min-device-pixel-ratio: 13/10),\n  only screen and (min-resolution: 120dpi) {\n    @content;\n  }\n}\n\n@mixin xSmallOnly {\n  @media screen and (max-width: #{$small - .0625rem}) {\n    @content;\n  }\n}\n\n@mixin smallOnly {\n  @media screen and (min-width: #{$small}) and (max-width: #{$medium - .0625rem}) {\n    @content;\n  }\n}\n\n@mixin mediumOnly {\n  @media screen and (min-width: #{$medium}) and (max-width: #{$large - .0625rem}) {\n    @content;\n  }\n}\n\n@mixin largeOnly {\n  @media screen and (min-width: #{$large}) and (max-width: #{$xLarge - .0625rem}) {\n    @content;\n  }\n}\n\n\n///////////////////////////////////////\n/// 2. FONTS\n///////////////////////////////////////\n\n$defaultSansSerif: 'Open Sans', sans-serif;\n$secondarySansSerif: 'Bebas Neue', sans-serif;\n\n$defaultSerif: 'Bree Serif', serif;\n$secondarySerif: 'Times New Roman', serif;\n\n$defaultMonospace: 'Courier New', monospace;\n\n///////////////////////////////////////\n/// 3. COLORS\n///////////////////////////////////////\n\n$backgroundGray: #fff;\n$darkGray:#a8a8a8;\n$lightGray:#d1d1d1;\n$greys: (\n  1: #e5e8e8,\n  2: #ccd3d3,\n  3: #8c9698,\n  4: #565d5f,\n  5: #191b1c,\n  6: #1a222b,\n  7: #f3f9ff\n);\n\n// Vuesora Colors\n$primary:#362063;\n$secondary:#42b983;\n\n// Brand Colors\n$drumeoBlue:#0B76DB;\n$guitareoGreen:#00C9AC;\n$guitareoGuitarQuestYellow:#FFB500;\n$guitareoGuitarQuestGray:#313131;\n$pianoteRed:#F61A30;\n$pianoteGreen:#232e31;\n$recordeoYellow:#FFAE00;\n$singeoPurple:#8300E9;\n\n$brand_colors: (\n  drumeo: $drumeoBlue,\n  guitareo: $guitareoGreen,\n  guitareoGuitarQuest: $guitareoGuitarQuestYellow,\n  pianote: $pianoteRed,\n  singeo: $singeoPurple,\n  recordeo: $recordeoYellow\n);\n\n// General Colors\n$successGreen:#4bb543;\n$warningYellow:#FFCC00;\n$errorRed:#F71B26;\n$liveRed:#F71B26;\n\n// Content Colors\n$content_colors: (\n  course: #07A0FF,\n  pack: #07A0FF,\n  song: #F8004F,\n  play-along: #FFB500,\n  student-focus: #A82FFF,\n  rudiment: #d06835,\n  dft: #0DD3BF,\n  learning-path: #0B76DB,\n  my-list: $drumeoBlue,\n  show: #00C278,\n  semester-pack: #00BC75,\n);\n\n$sidebarLink:#4D5356;\n\n$coachYellow:#FAA300;\n$lifetimeBlue:#07B3FF;\n\n/**\n* Make a horizontal gradient with 2 colors\n*\n* @param $primaryColor - the first color at the start of the gradient\n* @param $secondaryColor - the second color at the end of the gradient\n*/\n@mixin leftToRightGradient($primaryColor, $secondaryColor){\n  background: -moz-linear-gradient(left, $primaryColor 0%, $secondaryColor 100%);\n  background: -webkit-linear-gradient(left, $primaryColor 0%,$secondaryColor 100%);\n  background: linear-gradient(to right, $primaryColor 0%,$secondaryColor 100%);\n}\n\n/**\n* Make a vertical gradient with 2 colors\n*\n* @param $primaryColor - the first color at the start of the gradient\n* @param $secondaryColor - the second color at the end of the gradient\n*/\n@mixin topToBottomGradient($primaryColor, $secondaryColor){\n  background: -moz-linear-gradient(top, $primaryColor 0%, $secondaryColor 100%);\n  background: -webkit-linear-gradient(top, $primaryColor 0%,$secondaryColor 100%);\n  background: linear-gradient(to bottom, $primaryColor 0%,$secondaryColor 100%);\n}\n\n///////////////////////////////////////\n/// 4. POSITIONING\n///////////////////////////////////////\n\n@mixin flexCenter {\n  display:flex;\n  flex-direction:column;\n  justify-content:center;\n  align-items:center;\n}\n\n@mixin centerVertical {\n  position:absolute;\n  top:50%;\n  transform:translateY(-50%);\n  -webkit-transform:translateY(-50%);\n  -moz-transform:translateY(-50%);\n}\n\n@mixin centerHorizontal {\n  position:absolute;\n  left:50%;\n  transform:translateX(-50%);\n  -webkit-transform:translateX(-50%);\n  -moz-transform:translateX(-50%);\n}\n\n@mixin centerBoth {\n  position:absolute;\n  top:50%;\n  left:50%;\n  transform:translate(-50%, -50%);\n  -webkit-transform:translate(-50%,-50%);\n  -moz-transform:translate(-50%,-50%);\n}"],"sourceRoot":""}]);
